<script setup lang="ts">
import {displayText,displayJson,initials} from "../stores/presentation"
import VoiceInterview from './VoiceInterview.vue'
import {computed,ref} from 'vue'
import {api} from '../api'
import {desk,inr,label} from '../stores/desk'
import type {Case} from '../types'
const props=defineProps<{c:Case}>(),emit=defineEmits(['changed','evidence'])
const j=computed(()=>props.c.data.journey),manager=sessionStorage.getItem('msme_role')==='manager'
const v=ref({channel:'phone',identity_verified:false,business_verified:false,purpose_verified:false,notes:'',market_assessment:'',surveyor:'',survey_reference:'',property_value:0,margin_percent:25,title_clear:false,...props.c.data.journey?.verification})
const amount=ref(Number(props.c.data.requested_amount)),tenure=ref(props.c.data.tenure_months),rate=ref(props.c.data.annual_rate_percent??14),reason=ref(''),rateReason=ref(''),request=ref('')
const frozen=computed(()=>['approved','rejected','processing'].includes(props.c.status))
const nodes=[{key:'kyc',label:'Identity',x:80,y:60},{key:'bank',label:'Bank cash flow',x:280,y:60},{key:'tax',label:'GST / ITR',x:480,y:60},{key:'bureau',label:'Bureau risk',x:80,y:180},{key:'human',label:'Human verification',x:280,y:180},{key:'terms',label:'Loan terms',x:480,y:180}]
function ready(k:string){if(k==='tax')return j.value.sources?.gst?.status==='fetched'&&j.value.sources?.itr?.status==='fetched';if(k==='human')return !!j.value.verification;if(k==='terms')return ['approved','not_required'].includes(j.value.rate_exception?.status);return j.value.sources?.[k]?.status==='fetched'}
const selected=ref('kyc')
async function save(path:string,data:any){desk.busy=true;desk.error='';try{await api('/applications/'+props.c.id+'/'+path,{...data,revision:props.c.revision});emit('changed')}catch(e){desk.error=(e as Error).message}finally{desk.busy=false}}
function verification(){const {channel,identity_verified,business_verified,purpose_verified,notes,market_assessment,surveyor,survey_reference,property_value,margin_percent,title_clear}=v.value;return {channel,identity_verified,business_verified,purpose_verified,notes,market_assessment,surveyor,survey_reference,property_value,margin_percent,title_clear}}
async function ask(){desk.busy=true;desk.error='';try{await api('/applications/'+props.c.id+'/evidence-requests',{message:request.value});request.value='';emit('changed')}catch(e){desk.error=(e as Error).message}finally{desk.busy=false}}
</script>
<template><section v-if="j" class="journey-workspace"><div class="panel"><div class="section-title"><div><div class="eyebrow">THE COMPLETE BUSINESS PICTURE</div><h2>Every detail. Connected.</h2></div><span class="badge">{{displayText(label(j.loan_type))}}</span></div><div class="form-grid"><div><div class="applicant-identity"><span class="company-avatar">{{initials(c.data.applicant)}}</span><strong>{{displayText(c.data.applicant)}}</strong></div><p>{{displayText(j.pan)}} · {{displayText(j.sector||'Awaiting fetch')}} · {{displayText(j.classification?.category||'Classification pending')}}<br>{{displayText(j.udyam||'Udyam pending')}}<br>{{displayText(j.gstin||'GST verification pending')}}</p><span class="badge">Bureau {{displayText(j.bureau?.score??'Pending')}} / policy threshold 700</span><p>Existing monthly debt: {{displayText(inr(j.bureau?.monthly_debt))}}</p></div><div><strong>Consent & source traceability</strong><p>{{displayText(j.consents?.join(', '))}}<br>Recorded {{displayText(j.consent_at)}}</p><small>{{displayText(j.consent_id)}}</small><p>Follow each source to understand how it supports the assessment.</p></div></div>
<svg class="evidence-graph" viewBox="0 0 560 245" role="img" aria-label="Evidence graph connecting identity, cash flow, tax, bureau, verification and loan terms"><g stroke="#b9dce5" stroke-width="2"><path d="M80 60L280 60L480 60L280 180L80 60M80 180L280 60L480 180L280 180L80 180M480 60L480 180M80 60L80 180" fill="none"/></g><g v-for="n in nodes"><circle :cx="n.x" :cy="n.y" r="13" :fill="ready(n.key)?'#00a0b5':'#b17b30'"/><text :x="n.x" :y="n.y+33" text-anchor="middle">{{displayText(n.label)}}</text><text :x="n.x" :y="n.y+49" text-anchor="middle" class="graph-status">{{displayText(ready(n.key)?'Recorded':'Pending')}}</text></g></svg><div class="citations"><button v-for="n in nodes" @click="selected=n.key">{{displayText(n.label)}}</button></div><div class="source-detail"><div><span class="card-kicker">SOURCE DETAILS</span><h3>{{selected==='tax'?'Tax records':label(selected)}}</h3><p v-if="['kyc','bank','bureau','tax'].includes(selected)">Status: {{j.sources?.[selected==='tax'?'gst':selected]?.status==='fetched'?'Records received':'Awaiting records'}}</p><p v-else-if="selected==='human'">{{j.verification?.notes||'Your verification notes will appear here.'}}</p><p v-else>{{j.rate_exception?.reason||'The proposed terms follow the configured base rate.'}}</p><small v-if="j.sources?.[selected]?.fetched_at">Updated {{new Date(j.sources[selected].fetched_at).toLocaleString()}}</small></div><button @click="emit('evidence')">Explore evidence ↗</button></div></div>
<VoiceInterview :case-id="c.id" :revision="c.revision" :disabled="frozen" review-only @changed="emit('changed')" @notes="v.notes=$event;v.channel='voice'"/><div class="two-columns"><form class="panel" @submit.prevent="save('verification',verification())"><h2>A conversation that adds context.</h2><p>Review the voice transcript or record a manual interview. Confirm each check yourself; speech recognition does not perform biometric verification.</p><label>Verification channel<select v-model="v.channel"><option value="voice">Voice interview</option><option value="phone">Phone interview</option><option value="video">Video interview</option></select></label><label class="checkbox"><input type="checkbox" v-model="v.identity_verified">Identity verified</label><label class="checkbox"><input type="checkbox" v-model="v.business_verified">Business nature verified</label><label class="checkbox"><input type="checkbox" v-model="v.purpose_verified">Use of funds verified</label><label>Interview notes<textarea v-model="v.notes" required minlength="3" maxlength="2000"></textarea></label><label>Local market, viability & growth assessment<textarea v-model="v.market_assessment" required minlength="3" maxlength="2000"></textarea></label><template v-if="['lap','construction'].includes(j.loan_type)"><h3>Property & survey assessment</h3><label>Surveyor name<input v-model="v.surveyor" required maxlength="120"></label><label>Survey / title report reference<input v-model="v.survey_reference" required maxlength="160"></label><div class="form-grid"><label>Property value (INR)<input type="number" v-model.number="v.property_value" min="1" required></label><label>Margin (%)<input type="number" v-model.number="v.margin_percent" min="10" max="40" required></label></div><label class="checkbox"><input type="checkbox" v-model="v.title_clear">Title reviewed and clear</label></template><button class="primary" :disabled="desk.busy||frozen">Save verification</button><small>After saving, run analysis to regenerate the CAM.</small></form>
<div><form class="panel" @submit.prevent="save('terms',{amount,tenure_months:tenure,annual_rate_percent:rate,reason})"><h2>Shape the right proposal.</h2><p>Original request: {{displayText(inr(j.original_request.amount))}} / {{displayText(j.original_request.tenure_months)}} months</p><label>Proposed amount (INR)<input type="number" v-model.number="amount" min="1" max="100000000" required></label><label>Tenure (months)<input type="number" v-model.number="tenure" min="1" max="120" required></label><label>Annual interest rate (%)<input type="number" v-model.number="rate" min="0" max="100" step="0.1" required></label><label>Reason for proposed terms<textarea v-model="reason" minlength="3" maxlength="2000" required></textarea></label><button class="primary" :disabled="desk.busy||frozen">Save terms & require recalculation</button><div class="notice">Rate exception: <strong>{{displayText(label(j.rate_exception.status))}}</strong>. Every change from the configured base rate requires manager approval.</div></form>
<form class="panel" v-if="j.rate_exception.status==='pending'&&manager" @submit.prevent="save('rate-decision',{approve:true,reason:rateReason})"><h2>Manager rate exception decision</h2><p>{{displayText(j.rate_exception.base_rate)}}% → {{displayText(j.rate_exception.proposed_rate)}}%<br>{{displayText(j.rate_exception.reason)}}</p><label>Decision rationale<textarea v-model="rateReason" minlength="3" maxlength="2000" required></textarea></label><button class="primary" :disabled="desk.busy||frozen">Approve rate exception</button> <button type="button" @click="save('rate-decision',{approve:false,reason:rateReason})" :disabled="desk.busy||frozen||rateReason.trim().length<3">Reject rate exception</button><small>This approves the rate only. Regenerate CAM before final sanction.</small></form>
<form class="panel" @submit.prevent="ask"><h2>Keep the conversation moving.</h2><label>Specific gap and required evidence<textarea v-model="request" required minlength="3" maxlength="2000" placeholder="For example: supply the missing secondary bank statement covering the reporting year."></textarea></label><button :disabled="desk.busy||frozen">Send request to borrower</button></form></div></div></section></template>
